-- Maggie Lover shared database setup (safe, non-destructive)
-- Run in Supabase SQL Editor. This does NOT drop or truncate existing tables.
-- IMPORTANT: Create the admin user first in Authentication > Users, then replace the email below.

CREATE TABLE IF NOT EXISTS public.products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT '',
  price NUMERIC NOT NULL DEFAULT 0,
  image TEXT,
  description TEXT NOT NULL DEFAULT '',
  tags JSONB NOT NULL DEFAULT '[]'::jsonb,
  stock BOOLEAN NOT NULL DEFAULT TRUE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  discount_type TEXT NOT NULL DEFAULT 'none',
  discount_value NUMERIC NOT NULL DEFAULT 0,
  price_options JSONB NOT NULL DEFAULT '[]'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS name TEXT;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS category TEXT DEFAULT '';
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS price NUMERIC DEFAULT 0;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS image TEXT;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS description TEXT DEFAULT '';
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS tags JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS stock BOOLEAN DEFAULT TRUE;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT TRUE;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS discount_type TEXT DEFAULT 'none';
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS discount_value NUMERIC DEFAULT 0;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS price_options JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

CREATE TABLE IF NOT EXISTS public.categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS name TEXT;
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT TRUE;
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();
CREATE TABLE IF NOT EXISTS public.settings (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cafe_name TEXT NOT NULL DEFAULT 'Maggie Lover Café',
  open BOOLEAN NOT NULL DEFAULT TRUE,
  delivery_charge NUMERIC NOT NULL DEFAULT 30,
  min_order NUMERIC NOT NULL DEFAULT 99,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS cafe_name TEXT DEFAULT 'Maggie Lover Café';
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS open BOOLEAN DEFAULT TRUE;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS delivery_charge NUMERIC DEFAULT 30;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS min_order NUMERIC DEFAULT 99;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();
CREATE TABLE IF NOT EXISTS public.offers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  enabled BOOLEAN NOT NULL DEFAULT FALSE,
  type TEXT NOT NULL DEFAULT 'percentage',
  value NUMERIC NOT NULL DEFAULT 0,
  is_global BOOLEAN NOT NULL DEFAULT TRUE,
  scope TEXT NOT NULL DEFAULT 'global',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS enabled BOOLEAN DEFAULT FALSE;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS type TEXT DEFAULT 'percentage';
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS value NUMERIC DEFAULT 0;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS is_global BOOLEAN DEFAULT TRUE;
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS scope TEXT DEFAULT 'global';
ALTER TABLE public.offers ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();
CREATE TABLE IF NOT EXISTS public.customers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  orders INTEGER NOT NULL DEFAULT 0,
  spent NUMERIC NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS public.admin_users (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL UNIQUE,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Ensure order fields used by both apps exist. Existing data is preserved.
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS customer_id TEXT;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS customer JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS items JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS address JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS subtotal NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS delivery NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS delivery_charge NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS discount NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS total NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS payment TEXT NOT NULL DEFAULT 'Online Payment';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS payment_method TEXT NOT NULL DEFAULT 'Online Payment';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS delivery_name TEXT NOT NULL DEFAULT '';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS delivery_phone TEXT NOT NULL DEFAULT '';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tracking_code TEXT NOT NULL DEFAULT '';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tracking_token TEXT NOT NULL DEFAULT '';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS notes TEXT NOT NULL DEFAULT '';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

CREATE OR REPLACE FUNCTION public.is_maggie_admin()
RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public, auth AS $$
  SELECT EXISTS (SELECT 1 FROM public.admin_users a WHERE a.user_id = auth.uid() AND a.is_active = TRUE)
$$;
REVOKE ALL ON FUNCTION public.is_maggie_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_maggie_admin() TO anon, authenticated;

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;

-- Public/customer can only read active catalog/settings and submit orders.
DROP POLICY IF EXISTS ml_products_public_read ON public.products;
CREATE POLICY ml_products_public_read ON public.products FOR SELECT TO anon, authenticated USING (active = TRUE);
DROP POLICY IF EXISTS ml_categories_public_read ON public.categories;
CREATE POLICY ml_categories_public_read ON public.categories FOR SELECT TO anon, authenticated USING (active = TRUE);
DROP POLICY IF EXISTS ml_settings_public_read ON public.settings;
CREATE POLICY ml_settings_public_read ON public.settings FOR SELECT TO anon, authenticated USING (TRUE);
DROP POLICY IF EXISTS ml_offers_public_read ON public.offers;
CREATE POLICY ml_offers_public_read ON public.offers FOR SELECT TO anon, authenticated USING (TRUE);
DROP POLICY IF EXISTS customer_can_submit_order ON public.orders;
CREATE POLICY customer_can_submit_order ON public.orders FOR INSERT TO anon, authenticated WITH CHECK (TRUE);

-- Only approved admin users can read/update orders or manage catalog/settings.
DROP POLICY IF EXISTS ml_admin_orders_read ON public.orders;
CREATE POLICY ml_admin_orders_read ON public.orders FOR SELECT TO authenticated USING (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_orders_update ON public.orders;
CREATE POLICY ml_admin_orders_update ON public.orders FOR UPDATE TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_products_insert ON public.products;
CREATE POLICY ml_admin_products_insert ON public.products FOR INSERT TO authenticated WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_products_update ON public.products;
CREATE POLICY ml_admin_products_update ON public.products FOR UPDATE TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_products_delete ON public.products;
CREATE POLICY ml_admin_products_delete ON public.products FOR DELETE TO authenticated USING (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_categories_manage ON public.categories;
CREATE POLICY ml_admin_categories_manage ON public.categories FOR ALL TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_settings_manage ON public.settings;
CREATE POLICY ml_admin_settings_manage ON public.settings FOR ALL TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_offers_manage ON public.offers;
CREATE POLICY ml_admin_offers_manage ON public.offers FOR ALL TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_customers_manage ON public.customers;
CREATE POLICY ml_admin_customers_manage ON public.customers FOR ALL TO authenticated USING (public.is_maggie_admin()) WITH CHECK (public.is_maggie_admin());
DROP POLICY IF EXISTS ml_admin_users_read_self ON public.admin_users;
CREATE POLICY ml_admin_users_read_self ON public.admin_users FOR SELECT TO authenticated USING (user_id = auth.uid());

-- Safe customer tracking: order details are returned only when the unguessable token matches.
CREATE OR REPLACE FUNCTION public.get_order_tracking(p_order_id TEXT, p_tracking_token TEXT)
RETURNS JSONB LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public, auth AS $$
  SELECT jsonb_build_object(
    'id', o.id, 'items', o.items, 'subtotal', o.subtotal, 'delivery', o.delivery,
    'delivery_charge', o.delivery_charge, 'discount', o.discount, 'total', o.total,
    'payment', o.payment, 'payment_method', o.payment_method, 'payment_status', o.payment_status,
    'status', o.status, 'customer', o.customer, 'address', o.address,
    'delivery_name', o.delivery_name, 'delivery_phone', o.delivery_phone,
    'tracking_code', o.tracking_code, 'created_at', o.created_at, 'updated_at', o.updated_at
  ) FROM public.orders o
  WHERE o.id = p_order_id AND o.tracking_token = p_tracking_token
  LIMIT 1
$$;
REVOKE ALL ON FUNCTION public.get_order_tracking(TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_order_tracking(TEXT, TEXT) TO anon, authenticated;

GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT SELECT ON public.products, public.categories, public.settings, public.offers TO anon, authenticated;
GRANT INSERT ON public.orders TO anon, authenticated;
GRANT SELECT, UPDATE ON public.orders TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.products, public.categories, public.settings, public.offers, public.customers TO authenticated;
GRANT SELECT ON public.customers TO authenticated;
GRANT SELECT ON public.admin_users TO authenticated;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated;

SELECT 'Maggie Lover Café', TRUE, 30, 99
WHERE NOT EXISTS (SELECT 1 FROM public.settings);
SELECT FALSE, 'percentage', 0, TRUE, 'global'
WHERE NOT EXISTS (SELECT 1 FROM public.offers WHERE is_global = TRUE OR scope = 'global');


-- FINAL ADMIN ACCESS STEP:
-- 1) First create the admin account in Supabase > Authentication > Users.
-- 2) Replace admin@example.com below with the exact email of that account and run this block.
-- If the email has not been created yet, this inserts zero rows; create the user first and rerun it.
SELECT id, email FROM auth.users
WHERE lower(email) = lower('admin@example.com')
ON CONFLICT (user_id) DO UPDATE SET email = EXCLUDED.email, is_active = TRUE;
